function sharedNotesPage(){const isGM=actor==='mj';const notes=Array.isArray(state.sharedNotes)?state.sharedNotes:[];
 const fmt=at=>{try{return new Date(at).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});}catch{return '';}};
 const editor=(id,n)=>{const d=noteDrafts[id];const title=d?d.title:(n?n.title:'');const body=d?d.body:(n?n.body:'');return `<article class="panel note-card" data-note-card="${attr(id)}"><label class="field-label" for="note-title-${attr(id)}">Titre</label><input id="note-title-${attr(id)}" maxlength="80" value="${attr(title)}" data-note-field="title" data-note-id="${attr(id)}" placeholder="Ex. : Indices sur le sceau"><label class="field-label" for="note-body-${attr(id)}">Contenu</label><textarea id="note-body-${attr(id)}" class="note-text" rows="7" maxlength="4000" data-note-field="body" data-note-id="${attr(id)}" placeholder="Ce que le groupe a découvert, ses questions, ses plans…">${esc(body)}</textarea>${n?`<p class="muted small">Dernière modification par <strong>${esc(n.by)}</strong> · ${esc(fmt(n.at))}</p>`:''}<div class="note-actions"><button type="button" class="btn btn-primary" data-note-save="${attr(id)}">Enregistrer</button>${d?`<button type="button" class="btn btn-secondary" data-note-reset="${attr(id)}">Abandonner mes changements</button>`:''}${n?`<button type="button" class="btn btn-red" data-note-delete="${attr(id)}">Supprimer</button>`:''}</div></article>`;};
 const reader=n=>`<article class="panel note-card"><div class="panel-top"><h3>${esc(n.title)}</h3><span class="mini-pill">${esc(n.by)} · ${esc(fmt(n.at))}</span></div><p class="note-body">${esc(n.body)}</p></article>`;
 return `${heading('Suivi de la partie','Notes partagées des joueurs',isGM?'Lecture seule : ces notes sont écrites et modifiées par les joueurs de votre table.':'Un carnet commun à tous les joueurs de la table. Le MJ peut le lire, mais pas le modifier.')}
 <div class="planner-summary" data-tab="carnet"><span>${icon('notes')} ${notes.length} note${notes.length>1?'s':''}</span><span>${isGM?'👁 Accès en lecture':'✎ Chacun peut ajouter et modifier'}</span></div>
 ${isGM?'':`<div class="note-toolbar"><button type="button" class="btn btn-primary" data-task="note-new">＋ Nouvelle note</button></div>${noteDrafts.new?editor('new',null):''}`}
 ${liveFilter('.note-card',notes.length,'Filtrer les notes')}${notes.length?notes.map(n=>isGM?reader(n):editor(n.id,n)).join(''):`<div class="empty">${isGM?'Les joueurs n’ont pas encore écrit de note.':'Aucune note pour l’instant : créez la première.'}</div>`}`;}
function turnBanner(){if(actor==='mj'||page==='combat'||page==='overview'||!viewer||!state.combat?.started)return '';const me=L.findPc(state,actor);if(!me||L.activeId(state)!==me.id)return '';return `<div class="turn-banner" role="status"><span class="turn-seal" aria-hidden="true">${state.combat.round}</span><strong>À vous de jouer !</strong><span class="muted">Round ${state.combat.round} · ${esc(me.name)}</span><button type="button" class="btn btn-secondary" data-nav="combat">Mon tour</button></div>`;}
function defenseTags(p){const d=p.defenses||{};const short={resist:'Rés.',vuln:'Vuln.',immune:'Imm.'};return Object.entries(d).map(([t,v])=>`<span class="tag def-${v}" title="${esc(L.DEFENSE_STATES[v])} : ${esc(t)}">${short[v]} ${esc(t)}</span>`).join('');}
function defensePanel(p,edit,mode){const d=p.defenses||{},key='def-'+mode+'-'+p.id,n=Object.keys(d).length;
 return `<details class="ux-fold def-fold" data-fold="${attr(key)}" ${openFolds.has(key)?'open':''}><summary>Résistances et vulnérabilités${n?' · '+n:''} <span aria-hidden="true">⌄</span></summary><div class="ux-fold-content"><div class="def-grid">${L.DAMAGE_TYPES.map(t=>`<label class="def-cell def-${d[t]||'none'}"><span>${esc(t)}</span><select data-defense="${mode}|${attr(p.id)}|${attr(t)}" ${edit?'':'disabled'} aria-label="${esc(t)} : défense">${option('','Normal',d[t]||'')}${option('resist','Résistance',d[t]||'')}${option('vuln','Vulnérabilité',d[t]||'')}${option('immune','Immunité',d[t]||'')}</select></label>`).join('')}</div><p class="muted small">Appliquées quand un type de dégâts est choisi avant d’enregistrer les dégâts : résistance ÷ 2 (arrondi inférieur), vulnérabilité × 2, immunité 0.</p></div></details>`;}
const ABILITY_LABELS=[['str','FOR'],['dex','DEX'],['con','CON'],['int','INT'],['wis','SAG'],['cha','CHA']];
function npcStatBlock(n){const ab=n.abilities,mod=v=>{const m=Math.floor((v-10)/2);return (m>=0?'+':'−')+Math.abs(m);};
 const abil=ab?`<div class="npc-abilities" role="list" aria-label="Caractéristiques">${ABILITY_LABELS.map(([k,l])=>`<div role="listitem"><small>${l}</small><strong>${ab[k]}</strong><span>${mod(ab[k])}</span></div>`).join('')}</div>`:'';
 const tags=defenseTags(n),blocks=[['Traits',n.traits],['Actions légendaires',n.legendaryMax&&splitLegendary(n.legendary).length?'':n.legendary]].filter(x=>x[1]).map(([t,v])=>`<p class="muted small"><b>${t} :</b> ${esc(v)}</p>`).join('');
 return `${abil}${tags?`<div class="tagrow">${tags}</div>`:''}${blocks}${defensePanel(n,true,'npc')}`;}
// --- V4.4 : créatures lanceuses de sorts ---
function spellcastingFields(sc){const s=sc||{};return `<details class="ux-fold npc-form-group" ${sc?'open':''}><summary>Incantation (facultatif) <span aria-hidden="true">⌄</span></summary><div class="ux-fold-content"><div class="three-fields"><label>Caractéristique<select name="sc_ability"><option value="">—</option>${ABILITY_LABELS.map(([k,l])=>option(k,l,s.ability||'')).join('')}</select></label><label>DD des sorts<input name="sc_dc" type="number" min="1" max="40" value="${s.dc??''}"></label><label>Bonus d’attaque<input name="sc_attack" type="number" min="-10" max="30" value="${s.attack??''}"></label></div>
 <fieldset class="slot-fields"><legend>Emplacements par niveau</legend>${Array.from({length:9},(_,i)=>`<label>${i+1}<input name="sl_${i+1}" type="number" min="0" max="9" value="${s.slots?.[i]||0}"></label>`).join('')}</fieldset>
 <label>Sorts connus<textarea name="sc_spells" maxlength="1500" rows="3" placeholder="Tours de magie : Trait de feu · Niv. 1 : Bouclier, Projectile magique · Niv. 3 : Boule de feu">${esc(s.spells||'')}</textarea></label></div></details>`;}
function npcSpellBlock(n){const sc=n.spellcasting;if(!sc)return '';const used=n.slotsUsed||[];const levels=sc.slots.map((max,i)=>({l:i+1,max,left:max-(used[i]||0)})).filter(x=>x.max>0);
 return `<div class="npc-spells"><div class="npc-spells-top"><strong>Sorts</strong><span class="muted small">${sc.dc?'DD '+sc.dc:''}${sc.dc&&sc.attack!=null?' · ':''}${sc.attack!=null?(sc.attack>=0?'+':'')+sc.attack+' à l’attaque':''}${sc.ability?' · '+(ABILITY_LABELS.find(([k])=>k===sc.ability)||[])[1]:''}</span>${levels.length?`<button type="button" class="text-button" data-npc-slot-reset="${attr(n.id)}">Repos long</button>`:''}</div>
 ${levels.length?`<div class="slot-rows">${levels.map(x=>`<div class="slot-row"><span class="slot-level">Niv. ${x.l}</span><span class="legendary-pips" aria-label="${x.left} emplacement(s) de niveau ${x.l} sur ${x.max}">${Array.from({length:x.max},(_,i)=>`<i class="${i<x.left?'on':''}"></i>`).join('')}</span><button type="button" class="act-chip" data-npc-slot="${attr(n.id)}" data-level="${x.l}" data-delta="1" ${x.left<=0?'disabled':''}>Lancer</button><button type="button" class="text-button" data-npc-slot="${attr(n.id)}" data-level="${x.l}" data-delta="-1" ${x.left>=x.max?'disabled':''} aria-label="Rendre un emplacement de niveau ${x.l}">+1</button></div>`).join('')}</div>`:''}
 ${sc.spells?`<p class="small npc-spell-list">${esc(sc.spells)}</p>`:''}</div>`;}
function npcConcentrationBlock(n){const checks=n.concentrationChecks||[];
 if(!n.concentration)return `<details class="npc-conc"><summary>◎ Concentration…</summary><form class="npc-conc-form inline-form" data-npc="${attr(n.id)}"><label>Sort ou effet maintenu<input name="text" maxlength="60" required placeholder="Ex. Immobilisation de personne"></label><button class="btn btn-secondary" type="submit">Noter</button></form><p class="muted small">À chaque dégât, Chroniques rappelle la sauvegarde de Constitution (DD 10 ou moitié des dégâts).</p></details>`;
 return `<div class="npc-conc on"><span class="tag">◎ ${esc(n.concentration)}</span>${checks.map(c=>`<span class="conc-check" role="group" aria-label="Sauvegarde de concentration DD ${c.dc}">JS Con DD ${c.dc}<button type="button" class="text-button" data-npc-conc="${attr(n.id)}|${attr(c.id)}|success">Réussi</button><button type="button" class="text-button danger-text" data-npc-conc="${attr(n.id)}|${attr(c.id)}|failure">Raté</button></span>`).join('')}<button type="button" class="text-button" data-npc-conc-end="${attr(n.id)}">Terminer</button></div>`;}
function npcActionBar(n){const acts=splitActions(n.actions),leg=n.legendaryMax?splitLegendary(n.legendary):[],left=Number(n.legendaryLeft??n.legendaryMax)||0;if(!acts.length&&!leg.length)return '';
 return `<div class="npc-action-bar">${acts.length?`<div class="npc-acts" role="group" aria-label="Actions de ${attr(n.name)}">${acts.map(a=>{const rc=/\(recharge\s*(\d)(?:\s*-\s*6)?\)/i.exec(a.name),spent=rc&&(n.spent||[]).includes(a.name);return spent?`<button type="button" class="act-chip spent" data-npc-recharge="${attr(n.id)}" data-name="${attr(a.name)}" title="Dépensé : au début de son tour, lancez 1d6 ; sur ${rc[1]}${rc[1]==='6'?'':' ou plus'}, touchez pour le marquer rechargé.">⟳ ${esc(a.name.replace(/\s*\(recharge[^)]*\)/i,''))} · à recharger</button>`:`<button type="button" class="act-chip ${rc?'rechargeable':''}" data-npc-action="${attr(n.id)}" ${rc?`data-recharge="${attr(a.name)}"`:''} data-text="${attr(a.name+' — '+a.detail)}" data-hint="${attr(rollHint(a.detail))}" title="${attr(a.detail)}">${esc(a.name)}</button>`;}).join('')}${n.srd&&R?`<button type="button" class="act-chip sheet-chip" data-monster-sheet="${attr(n.srd)}" title="Bloc de statistiques officiel en français">📖 Fiche</button>`:''}</div>`:''}
 ${n.legendaryMax?`<div class="legendary-row"><span class="legendary-pips" aria-label="${left} action(s) légendaire(s) restante(s) sur ${n.legendaryMax}">${Array.from({length:n.legendaryMax},(_,i)=>`<i class="${i<left?'on':''}"></i>`).join('')}</span><strong>Actions légendaires ${left}/${n.legendaryMax}</strong>${leg.map(a=>`<button type="button" class="act-chip legendary" data-npc-legendary="${attr(n.id)}" data-cost="${a.cost}" data-text="${attr(a.detail)}" data-hint="${attr(rollHint(a.detail))}" ${left<a.cost?'disabled':''} title="${attr(a.detail)}">${esc(a.name)}${a.cost>1?' ('+a.cost+')':''}</button>`).join('')}<button type="button" class="text-button" data-npc-legendary-reset="${attr(n.id)}">Recharger</button></div>`:''}
 <p class="muted small">Un clic note l’action au journal du MJ et rappelle les dés à lancer. Les dés restent physiques.</p></div>`;}
// V4.9 — poste co-MJ : un écran consacré aux créatures (PV, états, concentration, actions légendaires,
// recharges, emplacements), pour un co-MJ ou une deuxième tablette du MJ. Adresse directe : /#poste-comj.
let comjFilter='alive';
function coGmPage(){const c=state.combat||{},npcs=c.npcs||[];const active=c.started?L.activeId(state):null;
 const order=c.order||[];const rank=n=>{const i=order.indexOf(n.id);return i<0?999:i;};
 const list=npcs.filter(n=>comjFilter==='all'||(comjFilter==='hidden'?n.visibility!=='public':n.hp>0)).slice().sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name,'fr'));
 const activeName=active?(npcs.find(n=>n.id===active)||L.findPc(state,active)||{}).name:'';
 return `${heading('Poste co-MJ','Créatures en jeu','Tout ce qu’il faut pour faire vivre les monstres pendant que le MJ principal mène la scène. Les jets restent physiques.')}
 <section class="panel comj-bar"><div class="comj-status">${c.started?`<strong>Round ${c.round}</strong><span>Au tour de <b>${esc(activeName||'—')}</b></span>${turnTimerBadge()}`:'<strong>Hors combat</strong><span class="muted">Préparez les créatures, puis lancez le combat depuis l’écran Combat.</span>'}</div>
 <div class="btn-group">${c.started?'<button type="button" class="btn btn-primary" data-task="next">Tour suivant →</button>':''}<button type="button" class="btn btn-secondary" data-nav="combat">Écran Combat</button><button type="button" class="btn btn-secondary" data-task="comj-link">Ouvrir sur un autre appareil</button></div>
 <div class="comj-filters" role="group" aria-label="Créatures affichées">${[['alive','Debout'],['all','Toutes'],['hidden','Masquées']].map(([id,l])=>`<button type="button" class="chip ${comjFilter===id?'selected':''}" aria-pressed="${comjFilter===id}" data-comj-filter="${id}">${l} (${id==='all'?npcs.length:id==='hidden'?npcs.filter(n=>n.visibility!=='public').length:npcs.filter(n=>n.hp>0).length})</button>`).join('')}</div></section>
 ${!c.started?`<details class="ux-fold comj-add"><summary>＋ Ajouter des créatures <span aria-hidden="true">⌄</span></summary><div class="ux-fold-content">${bestiaryPicker()}${(state.gmLibrary?.encounters||[]).length?`<div class="comj-enc"><strong>Rencontres prêtes :</strong> ${(state.gmLibrary.encounters).map(e=>`<button type="button" class="btn btn-secondary" data-encounter-deploy="${attr(e.id)}">${esc(e.name)}</button>`).join(' ')}</div>`:''}</div></details>`:''}
 ${list.length?`<div class="comj-grid">${list.map(n=>{const pct=Math.max(0,Math.min(100,Math.round(n.hp/Math.max(1,n.hpMax)*100)));return `<article class="comj-card ${n.id===active?'comj-active':''} ${n.hp<=0?'comj-down':''}" aria-label="${attr(n.name)}">
  <header><div>${artwork('npc',n.id,'','art-tiny',n.name)}<h3>${esc(n.name)}</h3><small class="muted">${n.kind==='pnj'?'PNJ':'Monstre'}${n.cr?' · FP '+esc(n.cr):''} · CA ${n.ac} · Init. ${n.initiative??'—'} · ${n.visibility==='public'?'Visible':'🔒 Masqué'}</small></div>${n.id===active?'<span class="tag">Son tour</span>':''}</header>
  <div class="comj-hp"><div class="comj-hpbar" role="progressbar" aria-label="Points de vie" aria-valuemin="0" aria-valuemax="${n.hpMax}" aria-valuenow="${n.hp}"><span class="${pct<=25?'danger':pct<=50?'warn':''}" style="width:${pct}%"></span></div><strong>${n.hp} / ${n.hpMax} PV</strong>${n.tempHp?` <small>+${n.tempHp} temp.</small>`:''}</div>
  <div class="npc-controls comj-hp-controls"><label>Total réel<input type="number" min="1" max="100000" value="1" inputmode="numeric" data-npc-amount="${attr(n.id)}"></label><button class="btn btn-red" data-npc-hp="damage" data-for="${attr(n.id)}">− Dégâts</button><button class="btn btn-secondary" data-npc-hp="heal" data-for="${attr(n.id)}">+ Soins</button><label>Type<select data-npc-type="${attr(n.id)}"><option value="">—</option>${L.DAMAGE_TYPES.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label></div>
  <div class="comj-conds">${(n.conditions||[]).map(x=>conditionChip(x,n.id)).join('')}<label class="visually-hidden" for="comj-cond-${attr(n.id)}">Ajouter ou retirer un état</label><select id="comj-cond-${attr(n.id)}" data-npc-condition="${attr(n.id)}"><option value="">＋ État…</option>${L.STATES.map(x=>option(x,((n.conditions||[]).includes(x)?'✓ ':'')+x,'')).join('')}</select></div>
  ${npcConcentrationBlock(n)}${npcActionBar(n)}${npcSpellBlock(n)}
  <details class="ux-fold"><summary>Bloc de statistiques <span aria-hidden="true">⌄</span></summary><div class="ux-fold-content">${npcStatBlock(n)}${n.notes?`<p class="secret-note">Notes secrètes : ${esc(n.notes)}</p>`:''}</div></details>
 </article>`;}).join('')}</div>`:`<p class="empty">${npcs.length?'Aucune créature pour ce filtre.':'Aucune créature en jeu.'}</p>`}`;}
function todayPageHtml(){const tpls=state.gmLibrary?.templates||[];return PR.todayPage({state,h:H6,extra:(CHR?`<div class="no-print">${CHR.recapPanel({state,isGM:true,h:H6})}</div>`:'')+(RTB?`<div class="no-print">${RTB.panel({state,isGM:true,h:H6,openId:rtOpen})}</div>`:'')+(DTM?`<div class="no-print">${DTM.gmPanel({state,h:H6})}</div>`:'')+groupCheckPanel()+votePanel()+tonguePanel(),fmtDate:fmtSession,partyRows:PT?PT.rows(state):[],difficulty:e=>difficultyLine((e.groups||[]).flatMap(g=>{const t=tpls.find(x=>x.id===g.templateId);return Array(g.quantity).fill(t?.cr||null);}))});}
function partyModal(){return `<div class="modal-backdrop"><div class="modal modal-wide party-modal" role="dialog" aria-modal="true" aria-labelledby="party-title"><div class="panel-top"><h2 id="party-title">Vue du groupe</h2><button class="icon-close" data-task="close-modal" aria-label="Fermer">✕</button></div>${PT.partyView({state,h:H6})}</div></div>`;}
function gmScreenModal(){return `<div class="modal-backdrop"><div class="modal modal-wide" role="dialog" aria-modal="true" aria-labelledby="gm-screen-title"><div class="panel-top"><h2 id="gm-screen-title">Écran du MJ</h2><button class="icon-close" data-task="close-modal" aria-label="Fermer">✕</button></div>
 <p class="muted small">Rappels des règles de base communes aux éditions 2014 et 2024, et vos règles maison marquées « Rappel dans l’Écran du MJ ». En cas de doute, la règle de la table et le livre priment.</p>
 ${liveFilter('.gm-screen-block dl > div',99,'Chercher une règle')}<div class="gm-screen">${TCHC&&TCHC.screenRules(state).length?`<section class="gm-screen-block gm-screen-house"><h3>Règles de la table</h3><dl>${TCHC.screenRules(state).map(r=>`<div><dt>${esc(r.title)}</dt><dd>${esc(r.text||'—')}</dd></div>`).join('')}</dl></section>`:''}${GM_SCREEN.map(([t,rows])=>`<section class="gm-screen-block"><h3>${esc(t)}</h3><dl>${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`).join('')}
 <section class="gm-screen-block"><h3>États</h3><dl>${L.STATES.map(c=>`<div><dt>${esc(c)}</dt><dd>${esc(conditionHelp(c)||'Voir les règles.')}</dd></div>`).join('')}</dl></section></div></div></div>`;}
function liveFilter(selector,count,label){return count>=4?`<label class="live-filter"><span class="muted small">${label}</span><input type="search" data-live-filter="${attr(selector)}" placeholder="Filtrer…" aria-label="${attr(label)}" autocomplete="off"></label>`:'';}
if(typeof document!=='undefined'&&typeof document.addEventListener==='function'){
 document.addEventListener('input',e=>{const el=e.target;if(el&&el.dataset&&el.dataset.histSearch!==undefined){histQuery=el.value;clearTimeout(window.__histTimer);window.__histTimer=setTimeout(render,150);return;}if(el&&el.id==='global-search'){searchSel=0;renderSearchResults();return;}if(el&&el.id==='rules-search'){rulesQuery=el.value;clearTimeout(window.__rulesTimer);window.__rulesTimer=setTimeout(()=>{const box=document.getElementById('rules-results');if(box)box.innerHTML=rulesResultsHtml();},120);return;}if(el&&el.closest&&el.closest('#rest-short-form')){const f=el.closest('form'),d=Number(f.dice.value)||0,t=Number(f.total.value)||0,box=document.getElementById('rest-preview');if(box&&d>0&&t>0)box.textContent='Soins : '+t+' + '+d+' × '+f.dataset.con+' (Constitution) = '+Math.max(d,t+d*Number(f.dataset.con))+' PV.';return;}if(el&&el.id==='item-catalog-search'){itemCatalogRender(el.value,el.dataset.character);return;}if(el&&el.closest&&el.closest('#add-form.wizard')){wizardRefresh(el.closest('form'));return;}if(el&&el.id==='lib-catalog-search'){libCatalogRender(el.value);return;}if(el&&el.dataset&&el.dataset.areaSize!==undefined){const v=Number(String(el.value).replace(',','.'));if(v>=1&&v<=150)areaSize=v;return;}if(el&&el.dataset&&el.dataset.libraryImageInput!==undefined){const box=document.getElementById('library-image-preview'),file=el.files?.[0];if(box&&file&&file.size<15_000_000){const fr=new FileReader();fr.onload=()=>{box.innerHTML='<img src="'+attr(String(fr.result))+'" alt="Aperçu">';};fr.readAsDataURL(file);}return;}if(el&&el.dataset&&el.dataset.iconPreview){const box=document.getElementById(el.dataset.iconPreview);if(box)box.innerHTML=el.value?'<img src="'+attr(A.src(el.value))+'" alt="">':'';return;}if(!el||!el.dataset||el.dataset.liveFilter===undefined)return;const q=String(el.value||'').toLocaleLowerCase('fr').trim();const root=el.closest('section,.panel,main')||document;for(const item of root.querySelectorAll(el.dataset.liveFilter))item.hidden=q!==''&&!String(item.textContent||'').toLocaleLowerCase('fr').includes(q);});
 document.addEventListener('keydown',e=>{
  if(window.ChroniquesTour&&window.ChroniquesTour.key(e)){e.preventDefault();return;}
  if(modal==='search'&&e.target&&e.target.id==='global-search'){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();searchSel=Math.max(0,Math.min(searchShown.length-1,searchSel+(e.key==='ArrowDown'?1:-1)));renderSearchResults();document.getElementById('sr-'+searchSel)?.scrollIntoView({block:'nearest'});return;}if(e.key==='Enter'){e.preventDefault();pickSearch(searchSel);return;}}
  if((e.ctrlKey||e.metaKey)&&!e.altKey&&String(e.key).toLowerCase()==='k'&&viewer){e.preventDefault();openSearch();return;}
  if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey)return;
  const t=e.target,typing=t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName||''));
  if(e.key==='Escape'){if(typeof modal!=='undefined'&&modal){modal='';render();}else if(helpOpen){helpOpen=false;render();}return;}
  if(typing||!viewer)return;
  if(e.key==='?'){e.preventDefault();helpOpen=!helpOpen;render();return;}
  if(e.key==='/'){const f=document.querySelector('input[type=search]');if(f){e.preventDefault();f.focus();}return;}
  if(actor==='mj'&&page==='combat'&&state&&state.combat&&state.combat.started){
   if(e.key==='n'||e.key==='N'){e.preventDefault();act('next');}
   else if(e.key==='u'||e.key==='U'){e.preventDefault();act('undo');}
  }
 });
}
