function libraryThumb(target,entry){const url=libraryImageUrl(target,entry);return url?`<img src="${attr(url)}" alt="" class="art-tiny library-photo" loading="lazy">`:entry?.icon?`<img src="${attr(A.src(entry.icon))}" alt="" class="art-tiny" loading="lazy">`:'';}
function libraryImageField(target,entry){const url=libraryImageUrl(target,entry);return `<fieldset class="library-image-field"><legend>Image personnelle (facultative)</legend><div class="library-image-row"><div class="library-image-preview" id="library-image-preview">${url?`<img src="${attr(url)}" alt="Image actuelle">`:'<span class="muted small">Aucune image importée</span>'}</div><div><label>Importer une image (JPG, PNG, WebP, HEIC)<input type="file" name="libraryImage" accept="image/png,image/jpeg,image/webp,image/heic,image/heif" data-library-image-input></label>${url?'<label class="inline-check"><input type="checkbox" name="libraryImageRemove"> Retirer l’image actuelle</label>':''}<p class="muted small">L’image est réduite et compressée sur votre appareil, puis stockée sur votre serveur. ${target==='handout'?'Elle':'Elle remplace l’icône ; elle'} accompagne ${target==='template'?'chaque créature ajoutée au combat (visible des joueurs seulement si la créature est révélée)':target==='handout'?'le document, visible uniquement des destinataires':'chaque exemplaire donné à un joueur'}.</p></div></div></fieldset>`;}
async function sendLibraryImage(target,id,form){const file=form.querySelector('[name="libraryImage"]')?.files?.[0],remove=form.querySelector('[name="libraryImageRemove"]')?.checked;if(!file&&!remove)return true;
 try{const body=remove&&!file?{target,id,remove:true,baseVersion:version}:{target,id,baseVersion:version,...await toUpload(file)};const out=await api('library/image','POST',body);state=out.state;version=out.version;viewer=out.viewer;return true;}
 catch(e){if(e.status===409){await refresh();}toast('Fiche enregistrée, mais image refusée : '+e.message,true);return false;}}
