function onboardingLoad(){try{onboardDone=OB.decode(JSON.parse(localStorage.getItem(OB.key(viewer?.name,onboardRole())+':'+String(viewer?.campaignId||''))||'{}'),onboardRole());}catch{onboardDone=[];}}
