function navButton(id,label,ico){return `<button type="button" class="navitem ${page===id?'active':''}" data-nav="${id}" aria-current="${page===id?'page':'false'}"><span>${icon(id,ico)}</span>${label}${navBadge(id)}</button>`;}
function mobileLink(id,symbol,label){return `<button type="button" class="mobile-nav-entry ${page===id?'active':''}" data-nav="${id}" aria-current="${page===id?'page':'false'}"><span aria-hidden="true">${icon(id,symbol)}</span><small>${label}${navBadge(id)}</small></button>`;}
