function buildSearchIndex(){const isGM=actor==='mj',out=[];const add=(label,sub,kind,run)=>out.push({label,sub,kind,run,key:fold(label+' '+(sub||''))});
 const pages=[['overview','Accueil'],['character','Fiche de personnage'],['combat','Combat'],['inventory','Inventaire & marchands'],['grimoire','Grimoire'],['rules','Règles du jeu (SRD)'],['table','Charte de la table'],['memorial','Mémorial'],['maps','Cartes'],['chronicle','Journal & quêtes'],['notes','Notes partagées'],['illustrations','Illustrations'],['settings','Paramètres'],['guide','Aide & tutoriel'],...(isGM?[['today','Séance du jour'],['comj','Poste co-MJ (créatures)'],['encounters','Bibliothèque MJ'],['session','Scènes de séance'],['stories','Assistant de scénario'],['campaign','Mes campagnes']]:[])];
 for(const [id,l] of pages)add(l,'Écran','Page',()=>goPage(id));
 const cmds=[['Écran du MJ','Règles courantes',()=>{modal='gm-screen';render();},isGM],['Carte X','Signal anonyme au MJ : écarter la scène en cours',()=>sendSignal('x'),!!TCHC],['Demander une pause','Signal anonyme au MJ',()=>sendSignal('pause'),!!TCHC],['Règles maison','Charte de la table',()=>goPage('table'),!!TCHC],['Dégâts de zone','Plusieurs cibles, sauvegardes et résistances',()=>{areaDmgPreset={keys:[],label:''};modal='area-damage';render();},isGM&&!!ADM],['Tables aléatoires','Lire le résultat de votre dé',()=>{goPage('today',()=>document.querySelector('.rt-panel')?.scrollIntoView({block:'start'}));},isGM&&!!RTB],['Vue du groupe','Sauvegardes, Perception passive, DD des sorts',()=>{modal='party';render();},isGM],['PNJ express','Nom, rôle, trait, voix, secret',()=>{modal='npc-express';render();},isGM],['Écran de table','Affichage pour TV ou vidéoprojecteur',()=>openTableScreen(),isGM],['Créer un monstre','Bestiaire maison',()=>{modal='tpl-new';render();},isGM],['Créer un objet','Objets maison',()=>{modal='libitem-new';render();},isGM],['Repos long pour tout le groupe','Repos',()=>restAllPrompt(),isGM],['Distribuer de l’XP','Récompenses',()=>goTab('chronicle','resumes',()=>document.getElementById('xp-award')?.scrollIntoView({block:'center'})),isGM],['Livre de campagne (PDF)','Impression',()=>printBook(),true],['Imprimer ma fiche','PDF',()=>{const id=isGM?selected:actor;if(id){modal='print:'+id;render();}},true],['Signaler un problème','Aide',()=>{modal='report';render();},true],['Taille du texte','Confort de lecture',()=>{textSize=(textSize+1)%3;try{localStorage.setItem('chroniques-taille',String(textSize));}catch{}applyTextSize();render();},true],['Quoi de neuf ?','Nouveautés de la version',()=>{modal='whats-new';render();},true]];
 for(const [l,s,run,ok] of cmds)if(ok)add(l,s,'Commande',run);
 for(const p of state.characters||[])add(p.name,[p.role,p.job,'niv. '+p.level].filter(Boolean).join(' · '),'Personnage',()=>{selected=p.id;goPage('character');});
 if(isGM)for(const n of state.combat?.npcs||[])add(n.name,n.hp+' / '+n.hpMax+' PV · en combat','Créature',()=>goPage('combat'));
 if(isGM)for(const t of state.gmLibrary?.templates||[])add(t.name,'Mon monstre'+(t.cr?' · FP '+t.cr:''),'Bestiaire maison',()=>{setPageTab('encounters','monstres');page='encounters';modal='tpl-edit:'+t.id;render();});
 if(isGM)for(const x of state.gmLibrary?.items||[])add(x.name,'Mon objet'+(HB?' · '+(HB.tagLine(x)||I.LABELS[x.category]):''),'Objet maison',()=>{setPageTab('encounters','objets');page='encounters';modal='libitem-edit:'+x.id;render();});
 for(const sh of state.shops||[])add(sh.name,sh.open?'Boutique ouverte':'Boutique fermée','Marchand',()=>isGM?goTab('encounters','marchands'):goPage('inventory',()=>document.querySelector('.shops-panel')?.scrollIntoView({block:'start'})));
 for(const h of state.handouts||[])add(h.title,isGM?(h.sentAt?'Document envoyé':'Brouillon'):(h.read?'Document lu':'Nouveau document'),'Document',()=>{handoutOpen=h.id;goTab('chronicle','documents');if(!isGM&&!h.read)act('handoutRead',{id:h.id});});
 for(const m of state.maps||[])add(m.title,'Carte','Carte',()=>{mapSelectedId=m.id;goPage('maps');});
 const planner=state.campaignPlanner||{};for(const [type,label] of PLANNER_TYPES)for(const e of planner[type]||[])add(e.title,label+(e.context?' · '+e.context:''),'Carnet',()=>goTab('chronicle','carnet',()=>document.getElementById('planner-'+type)?.scrollIntoView({block:'start'})));
 if(S&&Array.isArray(S.CATALOG))for(const sp of S.CATALOG)add(sp.name,(sp.level?'Sort de niveau '+sp.level:'Tour de magie')+(sp.school?' · '+sp.school:''),'Sort',()=>sp.srd&&R?openSpellDesc(sp.id):goPage('grimoire'));
 if(B)for(const m of B.list())add(m.name,(altNames(m)?altNames(m)+' · ':'')+'FP '+m.cr+' · '+m.type,'Bestiaire SRD',()=>isGM?goTab('encounters','monstres',()=>fillAndFire('input[data-live-filter=".bestiary-row"]',m.name)):goPage('combat'));
 return out;}
function searchResults(q){const n=fold(q).trim();let list=searchIndex;if(n){const words=n.split(/\s+/);list=searchIndex.filter(e=>words.every(w=>e.key.includes(w))).map(e=>({e,score:(fold(e.label).startsWith(n)?0:fold(e.label).includes(n)?1:2)+(e.kind==='Bestiaire SRD'||e.kind==='Sort'?0.5:0)})).sort((a,b)=>a.score-b.score||a.e.label.localeCompare(b.e.label,'fr')).map(x=>x.e);}
 else list=searchIndex.filter(e=>e.kind==='Page'||e.kind==='Commande');
 let extra=[];if(n.length>=2&&IC&&IC.loaded()){extra=IC.search(q,8).map(it=>({label:it.name,sub:(I.LABELS[it.category]||'Objet')+(it.rarity?' · '+it.rarity:''),kind:'Objet SRD',run:()=>actor==='mj'?goTab('encounters','objets',()=>{document.querySelector('#homebrew-items details')?.setAttribute('open','');fillAndFire('#lib-catalog-search',it.name);}):goPage('inventory',()=>{document.querySelector('.item-catalog')?.setAttribute('open','');fillAndFire('#item-catalog-search',it.name);})}));}
 if(n.length>=3&&R&&R.loaded())extra=extra.concat(R.search(q,8).filter(r=>r.kind==='rule').map(r=>({label:r.title,sub:r.chapterTitle,kind:'Règle',run:()=>{rulesSel=r.chapter+'|'+r.index;rulesQuery='';goPage('rules');}})));
 return list.slice(0,24).concat(extra).slice(0,32);}
let searchShown=[];
function renderSearchResults(){const box=document.getElementById('global-results'),input=document.getElementById('global-search');if(!box||!input)return;searchShown=searchResults(input.value);searchSel=Math.min(searchSel,Math.max(0,searchShown.length-1));
 box.innerHTML=searchShown.length?searchShown.map((r,i)=>`<li role="option" id="sr-${i}" aria-selected="${i===searchSel}" data-search-pick="${i}"><span class="sr-kind">${esc(r.kind)}</span><strong>${esc(r.label)}</strong>${r.sub?`<small>${esc(r.sub)}</small>`:''}</li>`).join(''):'<li class="muted small">Aucun résultat.</li>';input.setAttribute('aria-activedescendant',searchShown.length?'sr-'+searchSel:'');}
function openSearch(){if(R&&!R.loaded())R.load().then(()=>{if(modal==='search')renderSearchResults();}).catch(()=>{});if(B&&typeof needSrd==='function'&&actor==='mj')needSrd();if(IC&&!IC.loaded())IC.load().then(()=>{if(modal==='search')renderSearchResults();}).catch(()=>{});searchIndex=buildSearchIndex();searchSel=0;modal='search';render();setTimeout(()=>{document.getElementById('global-search')?.focus();renderSearchResults();},20);}
