function metersPerCell(map){const m=/([\d]+(?:[.,]\d+)?)/.exec(String(map.grid?.scale||'1,5'));return m?Number(m[1].replace(',','.')):1.5;}
const AREA_FILL={or:'#d4a64a',rouge:'#d0694f',bleu:'#5b86c9',vert:'#6aa577',violet:'#9a6cc4'};
function areasSvg(map,ratio){const list=map.areas||[];if(!list.length||!map.grid?.cells)return '';const H=1000/ratio,unit=metersPerCell(map)/(1000/map.grid.cells);const k=m=>m/unit;
 const shape=a=>{const X=a.x,Y=a.y/ratio,L=k(a.size),c=AREA_FILL[a.color]||AREA_FILL.rouge,t=a.angle*Math.PI/180,ux=Math.cos(t),uy=Math.sin(t),px=-uy,py=ux;const style=`fill="${c}" fill-opacity=".28" stroke="${c}" stroke-width="2" vector-effect="non-scaling-stroke"`;
  if(a.shape==='circle')return `<circle cx="${X}" cy="${Y}" r="${L}" ${style}/>`;
  if(a.shape==='cube')return `<rect x="${X-L/2}" y="${Y-L/2}" width="${L}" height="${L}" ${style}/>`;
  if(a.shape==='cone'){const ex=X+ux*L,ey=Y+uy*L;return `<polygon points="${X},${Y} ${ex+px*L/2},${ey+py*L/2} ${ex-px*L/2},${ey-py*L/2}" ${style}/>`;}
  const w=k(1.5)/2;return `<polygon points="${X+px*w},${Y+py*w} ${X+ux*L+px*w},${Y+uy*L+py*w} ${X+ux*L-px*w},${Y+uy*L-py*w} ${X-px*w},${Y-py*w}" ${style}/>`;};
 return `<svg class="map-areas" viewBox="0 0 1000 ${H}" preserveAspectRatio="none" aria-hidden="true">${list.map(shape).join('')}</svg>`;}
