function renderTable(){const app=$('#app');if(!app||!state)return;const maps=state.maps||[];const map=maps.find(m=>m.id===state.tableMapId&&m.hasImage)||maps.find(m=>m.hasImage);const ratio=map?(mapAspect[map.id]||1):1;
 const all=[...(state.characters||[]),...(state.combat?.npcs||[])];const order=(state.combat?.order||[]).map(id=>all.find(p=>p.id===id)).filter(Boolean);const active=state.combat?.started?state.combat.order[state.combat.index]:null;
 const stage=map?`<div class="campaign-map-stage table-stage ${map.grid?.cells&&map.grid?.shape!=='hex'?'with-grid':''}" style="--grid:${Number(map.grid?.cells)||1};width:min(100%,calc(96vh * ${ratio}))"><img class="campaign-map-image" src="/api/map-image/${encodeURIComponent(map.id)}" alt="" draggable="false" data-map-image="${attr(map.id)}">${map.grid?.cells&&map.grid?.shape!=='hex'?'<div class="map-grid" aria-hidden="true"></div>':''}${hexSvg(map,ratio,false)}${areasSvg(map,ratio)}${(map.tokens||[]).filter(t=>t.kind!=='pc'&&(!map.fog?.enabled||fogVisible(map,t.x,t.y))).map(t=>mapTokenHtml(map,t)).join('')}${map.fog?.enabled?fogSvg(map,ratio,false):''}${(map.tokens||[]).filter(t=>t.kind==='pc').map(t=>mapTokenHtml(map,t)).join('')}</div>`:`<div class="ts-empty"><h1>${esc(state.title||'Chroniques')}</h1>${nextSessionCard()}</div>`;
 const sp=state.spotlight;const spot=sp?`<div class="ts-spotlight"><img src="${attr(sp.builtinId?A.src(sp.builtinId):'/api/media/'+encodeURIComponent(sp.mediaId))}" alt=""><p>${esc(sp.title||'')}</p></div>`:'';
 const activeName=active?(all.find(p=>p.id===active)?.name||''):'';const recapShow=state.recapTable&&!state.combat?.started;
 patchApp(`<div class="table-screen"><main class="ts-main">${activeName?`<div class="ts-turn" role="status">Au tour de <strong>${esc(activeName)}</strong> · round ${state.combat.round}</div>`:''}${recapShow?`<div class="ts-recap table-recap">${CHR?CHR.paragraphs(state.recapTable,esc):esc(state.recapTable)}</div>`:stage}</main><aside class="ts-side"><h2>${esc(state.title||'')}</h2>${state.worldTime?.enabled&&WTC?`<p class="ts-date">${esc(WTC.season(state.worldTime,state.worldTime.minutes).icon)} ${esc(WTC.format(state.worldTime,state.worldTime.minutes))}</p>`:''}${turnTimerBadge(true)}${state.combat?.started?`<p class="ts-round">Round ${state.combat.round}</p><ol class="ts-init">${order.map(p=>{const pc=(state.characters||[]).some(c=>c.id===p.id);const hp=pc?p.hp+' / '+p.stats.hp:(p.showHp?p.hp+' / '+p.hpMax:'');return `<li class="${p.id===active?'active':''} ${pc?'pc':'npc'} ${(pc?p.hp:p.hp)<=0&&hp?'down':''}"><span>${esc(p.name)}</span>${hp?`<small>${hp} PV</small>`:''}</li>`;}).join('')}</ol>`:`<p class="ts-round">Hors combat</p>`}<button type="button" class="ts-full" data-ts-full>Plein écran</button></aside>${spot}</div>`);syncAudio();if(audioBlocked)showSoundUnlock();}
